        },
        complete() {
          observer.complete();
        },
      });
    });
  }
}

function createPipeline() {
  const middlewares = [];

  return {
    use(fn) {
      middlewares.push(fn);
      return this;
    },

    async execute(context) {
      let index = -1;

      async function dispatch(i) {
        if (i <= index) {
          throw new Error("next() called multiple times");
        }
        index = i;
        if (i < middlewares.length) {
          const fn = middlewares[i];
          await fn(context, () => dispatch(i + 1));
        }
      }

      await dispatch(0);
      return context;
    },
  };
}

