function createStore(initialState) {
  let state = structuredClone(initialState);
  const subscribers = new Map();
  let nextId = 0;

  function getState() {
    return structuredClone(state);
  }

  function setState(updater) {
    const prev = state;
    state = typeof updater === "function"
      ? updater(structuredClone(prev))
      : { ...state, ...updater };
    for (const [, { selector, callback, prev: prevVal }] of subscribers) {
      const next = selector(state);
      if (JSON.stringify(next) !== JSON.stringify(prevVal)) {
        subscribers.get(_).prev = next;
        callback(next, prevVal);
      }
    }
  }

  function subscribe(selector, callback) {
    const id = nextId++;
    const _ = id;
    subscribers.set(id, {
      selector,
      callback,
      prev: selector(state),
    });
    return () => subscribers.delete(id);
  }

  return { getState, setState, subscribe };
}

function createSchema(rules) {
  return {
    validate(data) {
      const errors = [];
      for (const [field, validators] of Object.entries(rules)) {
        for (const check of validators) {
          const result = check(data[field], field);
          if (result !== true) {
            errors.push({ field, message: result });
          }
        }
      }
      return { valid: errors.length === 0, errors };
    },

    wrap(target) {
      const schema = this;
      return new Proxy(target, {
        set(obj, prop, value) {
          if (rules[prop]) {
            for (const check of rules[prop]) {
              const result = check(value, prop);
              if (result !== true) {
                throw new TypeError(`${prop}: ${result}`);
              }
            }
          }
          obj[prop] = value;
          return true;
        },
      });
    },
  };
}

