function parse(tokens) {
  let pos = 0;

  function peek() {
    return tokens[pos];
  }

  function consume(expected) {
    const tok = tokens[pos];
    if (expected && tok !== expected) {
      throw new SyntaxError(`Expected ${expected}, got ${tok}`);
    }
    pos += 1;
    return tok;
  }

  function parseExpr() {
    let left = parseTerm();
    while (peek() === "+" || peek() === "-") {
      const op = consume();
      const right = parseTerm();
      left = { type: "BinOp", op, left, right };
    }
    return left;
  }

  function parseTerm() {
    let left = parsePrimary();
    while (peek() === "*" || peek() === "/") {
      const op = consume();
      const right = parsePrimary();
      left = { type: "BinOp", op, left, right };
    }
    return left;
  }

  function parsePrimary() {
    if (peek() === "(") {
      consume("(");
      const expr = parseExpr();
      consume(")");
      return expr;
    }
    return { type: "Num", value: Number(consume()) };
  }

  return parseExpr();
}

