async function* paginate(fetchPage) {
  let page = 1;
  let hasMore = true;

  while (hasMore) {
    const result = await fetchPage(page);
    if (result.items.length === 0) {
      hasMore = false;
    } else {
      for (const item of result.items) {
        yield item;
      }
      page += 1;
      hasMore = result.hasNext;
    }
  }
}

