function diff(oldNode, newNode) {
  if (typeof oldNode === "string" || typeof newNode === "string") {
    if (oldNode !== newNode) {
      return { type: "REPLACE", node: newNode };
    }
    return null;
  }
  if (oldNode.tag !== newNode.tag) {
    return { type: "REPLACE", node: newNode };
  }
  const propPatches = diffProps(oldNode.props, newNode.props);
  const childPatches = diffChildren(oldNode.children, newNode.children);
  if (propPatches.length === 0 && childPatches.every((p) => p === null)) {
    return null;
  }
  return { type: "UPDATE", propPatches, childPatches };
}

function diffProps(oldProps, newProps) {
  const patches = [];
  const allKeys = new Set([
    ...Object.keys(oldProps),
    ...Object.keys(newProps),
  ]);
  for (const key of allKeys) {
    if (oldProps[key] !== newProps[key]) {
      patches.push({
        key,
        value: newProps[key] !== undefined ? newProps[key] : null,
      });
    }
  }
  return patches;
}

function diffChildren(oldChildren, newChildren) {
  const patches = [];
  const maxLen = Math.max(oldChildren.length, newChildren.length);
  for (let i = 0; i < maxLen; i++) {
    if (i >= oldChildren.length) {
      patches.push({ type: "ADD", node: newChildren[i] });
    } else if (i >= newChildren.length) {
      patches.push({ type: "REMOVE" });
    } else {
      patches.push(diff(oldChildren[i], newChildren[i]));
    }
  }
  return patches;
}

