function reactive(target) {
  const deps = new Map();
  const computed = new Map();
  let activeEffect = null;

  const handler = {
    get(obj, prop) {
      if (computed.has(prop)) {
        const c = computed.get(prop);
        if (c.dirty) {
          const prev = activeEffect;
          activeEffect = prop;
          try {
            c.value = c.fn();
            c.dirty = false;
          } finally {
            activeEffect = prev;
          }
        }
        return c.value;
      }
      if (activeEffect !== null) {
        if (!deps.has(prop)) {
          deps.set(prop, new Set());
        }
        deps.get(prop).add(activeEffect);
      }
      return obj[prop];
    },
    set(obj, prop, value) {
      obj[prop] = value;
      if (deps.has(prop)) {
        for (const depKey of deps.get(prop)) {
          if (computed.has(depKey)) {
            computed.get(depKey).dirty = true;
          }
        }
      }
      return true;
    },
  };

  const proxy = new Proxy(target, handler);

  proxy.$computed = function (name, fn) {
    computed.set(name, { fn, value: undefined, dirty: true });
  };

  return proxy;
}

