class StateMachine {
  #current;
  #config;
  #context;
  #listeners = [];

  constructor(config) {
    this.#config = config;
    this.#current = config.initial;
    this.#context = structuredClone(config.context ?? {});
  }

  get state() {
    return this.#current;
  }

  get context() {
    return structuredClone(this.#context);
  }

  send(event, payload) {
    const stateConfig = this.#config.states[this.#current];
    if (!stateConfig?.on?.[event]) {
      return this;
    }
    const transitions = Array.isArray(stateConfig.on[event])
      ? stateConfig.on[event]
      : [stateConfig.on[event]];

    for (const transition of transitions) {
      const { target, guard, actions } = typeof transition === "string"
        ? { target: transition, guard: null, actions: [] }
        : transition;

      if (guard) {
        const guardFn = this.#config.guards?.[guard];
        if (guardFn && !guardFn(this.#context, { type: event, payload })) {
          continue;
        }
      }

      if (actions) {
        const actionList = Array.isArray(actions) ? actions : [actions];
        for (const actionName of actionList) {
          const actionFn = this.#config.actions?.[actionName];
          if (actionFn) {
            actionFn(this.#context, { type: event, payload });
          }
        }
      }

      const prev = this.#current;
      this.#current = target;
      for (const fn of this.#listeners) {
        fn({ from: prev, to: target, event, payload });
      }
      return this;
    }
    return this;
  }

  onTransition(fn) {
    this.#listeners.push(fn);
    return () => {
      this.#listeners = this.#listeners.filter((f) => f !== fn);
    };
  }
}

