        SUCCESS: { target: "done", actions: "setData" },
        FAILURE: [
          { target: "loading", guard: "canRetry", actions: "incrementRetry" },
          { target: "error" },
        ],
      },
    },
    done: { on: { RESET: "idle" } },
    error: { on: { RETRY: "loading" } },
  },
  guards: {
    canRetry: (ctx) => ctx.retries < 3,
  },
  actions: {
    resetRetries: (ctx) => { ctx.retries = 0; },
    incrementRetry: (ctx) => { ctx.retries += 1; },
    setData: (ctx, evt) => { ctx.data = evt.payload; },
  },
});

