class PluginHost {
  #plugins = [];
  #hooks = new Map();
  #context = {};

  register(plugin) {
    if (typeof plugin.name !== "string") {
      throw new Error("Plugin must have a name");
    }
    if (this.#plugins.some((p) => p.name === plugin.name)) {
      throw new Error(`Plugin "${plugin.name}" already registered`);
    }
    this.#plugins.push(plugin);
    return this;
  }

  hook(name, fn, { priority = 10 } = {}) {
    if (!this.#hooks.has(name)) {
      this.#hooks.set(name, []);
    }
    this.#hooks.get(name).push({ fn, priority });
    this.#hooks.get(name).sort((a, b) => a.priority - b.priority);
    return this;
  }

  async runHook(name, data) {
    const handlers = this.#hooks.get(name) ?? [];
    let result = data;
    for (const { fn } of handlers) {
      const output = await fn(result, this.#context);
      if (output !== undefined) {
        result = output;
      }
    }
    return result;
  }

  async initialize() {
    for (const plugin of this.#plugins) {
      if (typeof plugin.setup === "function") {
        await plugin.setup({
          hook: (name, fn, opts) => this.hook(name, fn, opts),
          context: this.#context,
        });
      }
    }
    await this.runHook("afterInit", null);
  }

  async shutdown() {
    await this.runHook("beforeShutdown", null);
    for (const plugin of [...this.#plugins].reverse()) {
      if (typeof plugin.teardown === "function") {
        await plugin.teardown(this.#context);
      }
    }
    this.#plugins = [];
    this.#hooks.clear();
  }
}

const host = new PluginHost();

host.register({
  name: "logger",
  async setup({ hook, context }) {
    context.logs = [];
    hook("transform", async (data, ctx) => {
      ctx.logs.push(`Processing: ${JSON.stringify(data)}`);
      return data;
    }, { priority: 1 });
    hook("afterInit", async (_, ctx) => {
      console.log("Logger plugin initialized");
    });
  },
  async teardown(ctx) {
    console.log(`Total logs: ${ctx.logs.length}`);
  },
});

host.register({
  name: "uppercase",
  async setup({ hook }) {
    hook("transform", async (data) => {
      if (typeof data === "string") {
        return data.toUpperCase();
      }
      return data;
    }, { priority: 5 });
  },
});

(async () => {
  await host.initialize();
  const result = await host.runHook("transform", "hello world");
  console.log(result);
  await host.shutdown();
})();
